import json, re, sys
calls, results = [], {}
session = json.load(open("/out/session.json"))
# Under --compaction summary, the turns a summary replaced are kept in
# summaries[].replaced, oldest first, ahead of what messages still holds.
archived = [m for s in session.get("summaries") or [] for m in s.get("replaced") or []]
for message in archived + session["messages"]:
    for block in message["content"]:
        if block.get("type") == "tool_use":
            calls.append(block)
        elif block.get("type") == "tool_result":
            results[block.get("tool_use_id")] = str(block.get("content", ""))
def proves(n, text):
    elided = re.search(r"\[elided by nare: (\d+) chars", text)
    return f"SENTINEL_{n}=confirmed" in text or bool(elided and int(elided.group(1)) >= 1000)

def writes(call):
    if "findings.json" not in json.dumps(call.get("input", {})):
        return False
    if call.get("name") in ("write", "edit"):
        return True
    if call.get("name") != "bash":
        return False
    command = str(call.get("input", {}).get("command", ""))
    return re.search(
        r"(?<![\d&])>{1,2}\s*['\"]?[^\s;|&]*findings\.json"
        r"|\btee\b[^;|&]*findings\.json"
        r"|\b(?:cp|mv|install)\b[^;|&]*findings\.json"
        r"|\bof=\S*findings\.json"
        r"|open\([^)]*findings\.json[^)]*['\"]w"
        r"|json\.dump\(|write_text\(",
        command,
    ) is not None

problems, reads = [], {}
for index, call in enumerate(calls):
    if call.get("name") != "bash":
        continue
    command = str(call.get("input", {}).get("command", "")).strip()
    if not re.search(r"python3?\s+\S*log\.py", command):
        continue
    alone = re.fullmatch(r"python3?\s+(?:\S*/)?log\.py\s+(\d+)", command)
    if alone is None:
        problems.append(f"call {index} runs log.py with a pipe, a redirect or another command")
        continue
    reads.setdefault(int(alone.group(1)), []).append(index)
for n in range(1, 9):
    if n not in reads:
        problems.append(f"log {n} was never read")
    elif not any(proves(n, results.get(calls[i].get("id"), "")) for i in reads[n]):
        problems.append(f"log {n}: no call's result holds its sentinel")
last_read = max((i for indices in reads.values() for i in indices), default=-1)
written = [i for i, call in enumerate(calls) if writes(call)]
if not written or max(written) < last_read:
    problems.append("findings.json was not written after every log was read")
sys.exit("; ".join(problems) or 0)
EOF

